import socket,json,pathlib,sys
rows=[]
for name in ["example.com","pypi.org"]:
 try:
  rows.append(dict(host=name,error_code=0,addresses=sorted({x[4][0] for x in socket.getaddrinfo(name,None)})))
 except socket.gaierror as e: rows.append(dict(host=name,error_code=e.errno,error=str(e)))
print(json.dumps(dict(resolv_conf=pathlib.Path("/etc/resolv.conf").read_text(),results=rows)))
sys.exit(any(r["error_code"]!=0 for r in rows))
